describe('tenantTermsOfUseProjectionToValue', () => {
  const value = {
    uid: 'value-uid',
    tenant: { $ref: 'ref-tenant' },
    resourceServer: { $ref: 'ref-resourceServer' },
    text: 'value-text',
    enabled: 'value-enabled',
    document: 'value-document',
    activationDate: 'value-activationDate',
    version: 'value-version',
  } as any;

  it('returns null without projection', () => {
    expect(tenantTermsOfUseProjectionToValue(null)).toBeNull();
    expect(tenantTermsOfUseProjectionToValue(undefined)).toBeNull();
  });

  it('keeps a plain value', () => {
    expect(tenantTermsOfUseProjectionToValue(value)).toEqual(value);
  });

  it('reduces the projected references to their key', () => {
    const projection = {
      uid: 'value-uid',
      tenant: () => ({ uid: 'ref-tenant' }),
      resourceServer: () => ({ uid: 'ref-resourceServer' }),
      text: 'value-text',
      enabled: 'value-enabled',
      document: 'value-document',
      activationDate: 'value-activationDate',
      version: 'value-version',
    } as any;
    expect(tenantTermsOfUseProjectionToValue(projection)).toEqual(value);
  });
});
